import {createPlayer,item,stats,CLASSES} from './core.js?v=26';
import {advanceXP,mobReward,enchant,enchantPrice} from './progression.js?v=26';
import {trainingQuote,buyTraining} from './supremacy.js?v=26';
import {basicInterval,resolveStrike} from './combat.js?v=26';
import {KITS} from './skills.js?v=26';
import {findPath} from './navigation.js?v=26';
export const VIP_TIERS=[{level:0,name:'Aventureiro Free',threshold:0,bonus:0},{level:1,name:'Pacto Prata',threshold:10000,bonus:.05},{level:2,name:'Pacto Ouro',threshold:50000,bonus:.10},{level:3,name:'Pacto Astral',threshold:200000,bonus:.15},{level:4,name:'Pacto Soberano',threshold:1000000,bonus:.20}];
export function vipState(p){p.vip||={spent:0};return [...VIP_TIERS].reverse().find(v=>(p.vip.spent||0)>=v.threshold)||VIP_TIERS[0];}
export function buyVip(p,level){const tier=VIP_TIERS.find(t=>t.level===level);if(!tier||level===0)return{ok:false,reason:'Selecione um pacto.'};const old=vipState(p),price=Math.max(0,tier.threshold-(p.vip.spent||0));if(level<=old.level)return{ok:false,reason:'Este pacto já está ativo.'};if((p.wallet?.cash||0)<price)return{ok:false,reason:'Cash de teste insuficiente.'};p.wallet.cash-=price;p.vip.spent+=price;return{ok:true,price,tier};}
const NAMES=['Aeloria','KaelRiven','NyxVesper','ThorinSol','Lyriel','DanteAsh','MiraLune','Ragnar','Selka','Auron','Elowen','Noctis','YunaFrost','Valdrik','Lysander','AriaVale','Zarek','Freya','Kuro','Seraphine','Altair','Sylas','Nerissa','Valkor','KiraDawn','Ezra','Sora','Isolde','Fenris','Liora','RivenGold','AkiraLux','VeraNova','Oberon','Cassia','Zephyr','Draven','Eira','Lucian','Astrid','Raiden','Naelia','Asterion','Zafira','Balthor','Elysia','Kaine','Aurielle','Veyron','Lunaris'];
const IDS=['VIG','ARC','RUP','LAS'];
export function rngFrom(seed){let n=seed>>>0;return()=>{n=(Math.imul(n,1664525)+1013904223)>>>0;return n/4294967296;};}
export function allocate(p){const total=(p.level-1)*5,ratio=p.classId==='ARC'?[.1,.8,.1]:p.classId==='VIG'?[.2,0,.8]:p.classId==='RUP'?[.8,0,.2]:[.4,.3,.3];p.attributes={for:Math.floor(total*ratio[0]),int:Math.floor(total*ratio[1]),des:0};p.attributes.des=total-p.attributes.for-p.attributes.int;}
export function createSociety(now=Date.now()){return {version:2,createdAt:now,lastTickAt:now,elapsedSeconds:0,days:0,party:[],messages:[],arena:{wins:0,losses:0,draws:0},bots:NAMES.map((name,i)=>{const profile=i<30?'free':i<42?'vip':'patron',p=createPlayer(IDS[i%4],name);p.testMode=false;p.wallet={cash:0};p.vip={spent:0};p.skillRanks=Object.fromEntries(Array.from({length:7},(_,n)=>[n,1]));allocate(p);const st=stats(p);p.hp=st.hp;p.mp=st.mp;const home=i%21;return{id:'bot-'+i,name,classId:p.classId,profile,personality:['explorador','competitivo','prestativo','colecionador'][i%4],intent:'Reconhecendo o acampamento',player:p,homeRegion:home,region:home,zone:'coast',x:16+Math.floor(i/21)*2.5,y:17+(i%3)*1.6,wins:0,losses:0,days:0,kills:0,quests:0,spent:0,loot:0,seed:4800+i,cooldown:0,ageSeconds:0,fundedDays:-1,task:'outbound',wait:0,goal:{x:20+(i%3),y:18+(i%2)*2},journal:[]};})};}
export function ensureSociety(p,now=Date.now()){if(!p.society||p.society.version!==2||p.society.bots?.length!==50){if(p.society){p.societyArchive={version:p.society.version,archivedAt:now,arena:p.society.arena,bots:p.society.bots?.map(b=>({name:b.name,level:b.player?.level,wins:b.wins,losses:b.losses})),messages:p.society.messages?.slice(-30)};}p.society=createSociety(now);}return p.society;}
export function simulateBotDay(bot){const p=bot.player,rng=rngFrom(bot.seed+bot.days*97),hours=bot.profile==='patron'?4:bot.profile==='vip'?3:2,kills=Math.round(hours*(80+rng()*40));bot.days++;bot.kills+=kills;p.wallet.cash+=bot.profile==='free'?0:bot.profile==='vip'?10000:100000;p.shards+=Math.round(kills*.35);const reward=mobReward(p,p.level,false);p.gold+=reward.gold*(kills-1);for(const [k,v] of Object.entries(reward.mats))p.materials[k]=(p.materials[k]||0)+v*(kills-1);p.materials['Fragmento de Magícula']=(p.materials['Fragmento de Magícula']||0)+kills;const vip=vipState(p);p.gold+=Math.round(reward.gold*kills*vip.bonus);p.materials['Fragmento de Magícula']+=Math.floor(kills*vip.bonus);advanceXP(p,reward.xp*kills);allocate(p);const before=p.wallet.cash;if(bot.profile!=='free'&&p.level<1000){const q=trainingQuote(p);if(q.ok&&q.price<=p.wallet.cash){const bought=buyTraining(p);if(bought.ok)advanceXP(p,bought.xp);}}
 const weapon=p.bag.find(i=>i.slot==='weapon');if(weapon&&weapon.enchant<100){const price=enchantPrice(weapon.enchant);if(p.gold>=price.gold&&p.shards>=price.crystals)enchant(p,weapon,rng);}if(weapon&&p.level-weapon.level>=25){const fresh=item(p.classId,p.level,'weapon',p.level>=250?'SSS':p.level>=175?'SS+':'A',rng);p.bag=p.bag.filter(i=>i.slot!=='weapon');p.bag.push(fresh);p.equipped.weapon=fresh.id;bot.loot++;}bot.spent+=Math.max(0,before-p.wallet.cash);allocate(p);return stats(p);}
export async function simulateDays(world,days,onProgress=()=>{}){days=Math.max(1,Math.min(30,Math.floor(days)||1));const before=cohortReport(world);for(let d=0;d<days;d++){for(const bot of world.bots)simulateBotDay(bot);world.days++;onProgress(d+1,days);await new Promise(resolve=>setTimeout(resolve,0));}return{days,before,after:cohortReport(world)};}
export function cohortReport(world){return ['free','vip','patron'].map(profile=>{const rows=world.bots.filter(b=>b.profile===profile);return{profile,count:rows.length,level:Math.round(rows.reduce((a,b)=>a+b.player.level,0)/rows.length),power:Math.round(rows.reduce((a,b)=>a+stats(b.player).pc,0)/rows.length),spent:rows.reduce((a,b)=>a+b.spent,0),kills:rows.reduce((a,b)=>a+b.kills,0)};});}
export function inviteBot(world,id){const bot=world.bots.find(b=>b.id===id);if(!bot)return{ok:false,reason:'Bot não encontrado.'};if(world.party.includes(id)){world.party=world.party.filter(v=>v!==id);return{ok:true,removed:true};}if(world.party.length>=4)return{ok:false,reason:'Grupo completo: você e quatro aliados.'};world.party.push(id);return{ok:true};}
export function botReply(bot,message,world){const text=String(message).toLowerCase(),p=bot.player,v=vipState(p);if(/\b(ol[aá]|oi)\b|e a[ií]/.test(text))return`Oi! Sou ${bot.name}, ${CLASSES[bot.classId].name}. Estou ${bot.intent.toLowerCase()}. Quer conversar, formar grupo ou treinar?`;if(/grupo|junto|ajud|dg|masmorra/.test(text))return world.party.includes(bot.id)?'Estou no seu grupo! Vou seguir você e atacar o alvo quando você entrar em combate. Entre na masmorra pelo Atlas.':'Posso acompanhar você. Use CONVIDAR neste perfil; o grupo tem espaço para quatro bots além de você.';if(/vip|cash|gast|free/.test(text))return bot.profile==='free'?'Meu perfil é free: não recebo cash na simulação. Farmo materiais e tento aprimorar com ouro e cristais.':`Meu perfil é ${bot.profile==='patron'?'alto investimento':'VIP'}. Uso cash simulado para treinamento quando o saldo cobre a cotação. Pacto: ${v.name}.`;if(/arma|item|equip|poder|build/.test(text))return`Tenho ${stats(p).pc.toLocaleString('pt-BR')} de poder e arma +${p.bag.find(i=>i.slot==='weapon')?.enchant||0}. ${bot.classId==='VIG'?'Busco cadência e críticos.':bot.classId==='ARC'?'Busco AMP mágica e penetração.':'Busco AMP espada, crítico e penetração.'}`;if(/arena|pvp|duelo/.test(text))return`Tenho ${bot.wins} vitórias e ${bot.losses} derrotas em duelos simulados. Use DESAFIAR. Na arena equalizada o orçamento de atributos é igualado; no modo livre vale a build atual.`;if(/hist[oó]ria|miss[aã]o|objetivo/.test(text))return'Aster transforma memórias em poder. Siga as Crônicas e as Ordens do Farol: elas mostram o objetivo atual e os títulos que você pode conquistar.';return [`Estou no nível ${p.level}. Meu objetivo agora: ${bot.intent.toLowerCase()}. Pode perguntar sobre build, VIP, história, grupo ou arena.`,`Como ${bot.personality}, eu prefiro ${bot.personality==='competitivo'?'testar minha execução na arena':'preparar a build antes de enfrentar um chefe'}. Em que você está trabalhando?`][message.length%2];}
export function tickFollowers(world,p,enemies,dt,blocked,onStrike){const followers=world.bots.filter(b=>world.party.includes(b.id)&&!(b.joinTravel>0));for(const [index,b] of followers.entries()){b.cooldown=Math.max(0,(b.cooldown||0)-dt);b.attackAnim=Math.max(0,(b.attackAnim||0)-dt);if(b.zone!==p.zone||b.region!==(p.region||0)||Math.hypot(b.x-p.x,b.y-p.y)>20){b.x=p.x-1;b.y=p.y+1;b.zone=p.zone;b.region=p.region||0;b.route=[];}const gx=p.x-2.5-(index%2)*1.6,gy=p.y+1.7+Math.floor(index/2)*1.6;if(!b.routeGoal||Math.hypot(b.routeGoal.x-gx,b.routeGoal.y-gy)>1.5){b.routeGoal={x:gx,y:gy};b.route=findPath(b,b.routeGoal,(x,y)=>blocked(x,y,p.zone));}while(b.route?.length&&Math.hypot(b.route[0].x-b.x,b.route[0].y-b.y)<.25)b.route.shift();const goal=b.route?.[0];b.moving=!!goal;if(goal){const dx=goal.x-b.x,dy=goal.y-b.y,l=Math.hypot(dx,dy),step=Math.min(l,dt*4.5);if(l){b.x+=dx/l*step;b.y+=dy/l*step;}}if(!b.cooldown){const st=b.cachedStats||(b.cachedStats=stats(b.player)),target=enemies.find(e=>e.hp>0&&!e.training&&e===world.combatTarget&&Math.hypot(e.x-b.x,e.y-b.y)<=st.range+2);if(target){const sk=KITS[b.classId].findIndex(k=>k.coef>0&&k.range>=Math.hypot(target.x-b.x,target.y-b.y));b.turn=(b.turn||0)+1;const index=b.turn%3===0&&sk>=0?sk:null;const out=resolveStrike(st,b.classId,target,{index,coefficient:index===null?1:KITS[b.classId][index].coef});b.cooldown=Math.max(.4,basicInterval(st));b.attackAnim=.5;onStrike(b,target,out,index);}}}return followers;}
export function applyVipReward(p,reward,boss=false){if(boss)return{gold:0,fragments:0};const v=vipState(p),gold=Math.round((reward.gold||0)*v.bonus);p.gold+=gold;p.vip.fragmentCarry=(p.vip.fragmentCarry||0)+v.bonus;const fragments=Math.floor(p.vip.fragmentCarry+1e-9);p.vip.fragmentCarry=Math.max(0,p.vip.fragmentCarry-fragments);if(fragments){p.materials||={};p.materials['Fragmento de Magícula']=(p.materials['Fragmento de Magícula']||0)+fragments;}return{gold,fragments};}
